package com.colovision.model;
import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="predictions") public class Prediction { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="patient_id") public Long patientId; @Column(name="image_path") public String imagePath; @Column(name="segmentation_path") public String segmentationPath; @Column(name="overlay_path") public String overlayPath; @Column(name="predicted_class") public String predictedClass; public double confidence; @Column(name="adenocarcinoma_probability") public double adenocarcinomaProbability; @Column(name="high_grade_probability") public double highGradeProbability; @Column(name="low_grade_probability") public double lowGradeProbability; @Column(name="normal_probability") public double normalProbability; @Column(name="polyp_probability") public double polypProbability; @Column(name="serrated_probability") public double serratedProbability; @Column(name="created_at") public Instant createdAt=Instant.now(); @JsonIgnore @ManyToOne @JoinColumn(name="patient_id",insertable=false,updatable=false) public Patient patient; }
